use std::io::*;

const NIL: usize = usize::MAX;

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut out = String::new();
    let mut key: Vec<i64> = vec![];
    let mut l: Vec<usize> = vec![];
    let mut r: Vec<usize> = vec![];
    let mut root = NIL;
    for line in s.lines() {
        let mut it = line.split_whitespace();
        let cmd = match it.next() {
            Some(c) => c,
            None => continue,
        };
        let x: i64 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
        match cmd {
            "insert" | "contains" | "delete" => {
                let mut cur = root;
                let mut par = NIL;
                let mut left = false;
                while cur != NIL && key[cur] != x {
                    par = cur;
                    if x < key[cur] {
                        left = true;
                        cur = l[cur];
                    } else {
                        left = false;
                        cur = r[cur];
                    }
                }
                if cmd == "contains" {
                    out.push_str(if cur != NIL { "yes\n" } else { "no\n" });
                } else if cmd == "insert" {
                    if cur != NIL {
                        out.push_str("dup\n");
                    } else {
                        key.push(x);
                        l.push(NIL);
                        r.push(NIL);
                        let id = key.len() - 1;
                        if par == NIL {
                            root = id;
                        } else if left {
                            l[par] = id;
                        } else {
                            r[par] = id;
                        }
                        out.push_str("ok\n");
                    }
                } else if cur == NIL {
                    out.push_str("missing\n");
                } else {
                    if l[cur] != NIL && r[cur] != NIL {
                        let mut sp = cur;
                        let mut sleft = false;
                        let mut sc = r[cur];
                        while l[sc] != NIL {
                            sp = sc;
                            sleft = true;
                            sc = l[sc];
                        }
                        key[cur] = key[sc];
                        if sleft {
                            l[sp] = r[sc];
                        } else {
                            r[sp] = r[sc];
                        }
                    } else {
                        let ch = if l[cur] != NIL { l[cur] } else { r[cur] };
                        if par == NIL {
                            root = ch;
                        } else if left {
                            l[par] = ch;
                        } else {
                            r[par] = ch;
                        }
                    }
                    out.push_str("ok\n");
                }
            }
            "inorder" => {
                if root == NIL {
                    out.push_str("<empty>\n");
                } else {
                    let mut st = vec![];
                    let mut cur = root;
                    let mut v = vec![];
                    while cur != NIL || !st.is_empty() {
                        while cur != NIL {
                            st.push(cur);
                            cur = l[cur];
                        }
                        let n = st.pop().unwrap();
                        v.push(key[n].to_string());
                        cur = r[n];
                    }
                    out.push_str(&v.join(" "));
                    out.push('\n');
                }
            }
            "height" => {
                let mut best = 0;
                let mut st = vec![];
                if root != NIL {
                    st.push((root, 1));
                }
                while let Some((n, d)) = st.pop() {
                    if d > best {
                        best = d;
                    }
                    if l[n] != NIL {
                        st.push((l[n], d + 1));
                    }
                    if r[n] != NIL {
                        st.push((r[n], d + 1));
                    }
                }
                out.push_str(&format!("{}\n", best));
            }
            "min" | "max" => {
                if root == NIL {
                    out.push_str("empty\n");
                } else {
                    let mut c = root;
                    let nx = if cmd == "min" { &l } else { &r };
                    while nx[c] != NIL {
                        c = nx[c];
                    }
                    out.push_str(&format!("{}\n", key[c]));
                }
            }
            _ => {}
        }
    }
    print!("{}", out);
}

